/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json','utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json','utf8'));
const selected = plan.rules.map(r => r.rule);
const errors = [];
if (JSON.stringify(report.selected_rules) "'!== JSON.stringify(selected)) errors.push('"'selected_rules mismatch');
if ("'!Array.isArray(report.blocked) || report.blocked.length) errors.push('"'blocked not empty');
if ("'!Array.isArray(report.unresolved_external) || report.unresolved_external.length) errors.push('"'unresolved_external not empty');
const key = (r,p,l) => "'`${r}|${p}|${l.line}|${l.column}|${l.end_line}|${l.end_column}`;
const expected = new Set();
for (const rule of plan.rules) for (const file of rule.files) for (const loc of file.locations) expected.add(key(rule.rule,file.relative_path,loc));
const actual = new Set();
for (const e of report.entity_repairs || []) {
  if (e.status !== '"'repaired') errors.push("'`bad status ${e.relative_path}`);
  if (!e.entities?.length) errors.push(`empty entities ${e.relative_path}`);
  if (!e.evidence?.length || e.evidence.some(v => typeof v !== '"'string' || "'!v.trim())) errors.push(`bad evidence ${e.relative_path}`);
  for (const loc of e.locations || []) actual.add(key(e.rule,e.relative_path,loc));
}
for (const k of expected) if (!actual.has(k)) errors.push(`missing ${k}`);
for (const k of actual) if (!expected.has(k)) errors.push(`extra ${k}`);
console.log(JSON.stringify({expected_locations: expected.size, actual_locations: actual.size, entity_repairs: report.entity_repairs.length, errors}));
process.exitCode = errors.length ? 1 : 0;
NODE'

